import { exhaustiveCheck, multipleClassNames } from "@/core/helpers";
import Icon from "@/core/components/primitives/icon/icon";
import Link from "@/core/components/primitives/link/link";
import styles from "./broadcast-message.module.less";

/**
 * All properties are intentionally optional to be defensive — the broadcast banner
 * should never break even if individual fields are missing from the CMS data.
 */
export type BroadcastMessageLink = {
  title?: string;
  smallDeviceTitle?: string;
  internalLink?: {
    slug: string;
  };
  externalUrl?: string;
};

export type BroadcastMessageProps = {
  broadcastMessageContent?: {
    childMarkdownRemark?: {
      html: string;
    };
  };
  broadcastMessageStatus?: "Hide" | "General info" | "Important info" | "Critical info";
  broadcastMessageLink?: BroadcastMessageLink;
};

export const handleBroadcastMessageStatus = ({
  broadcastMessageStatus,
}: Pick<BroadcastMessageProps, "broadcastMessageStatus">) => {
  const status = (() => {
    switch (broadcastMessageStatus) {
      case "Hide":
        return "hide";
      case "General info":
        return "general";
      case "Important info":
        return "important";
      case "Critical info":
        return "critical";
      case undefined:
        return "hide";
      default:
        exhaustiveCheck(broadcastMessageStatus);
        return "hide";
    }
  })();
  return { status, shouldShow: status !== "hide" } as const;
};

const BroadcastMessage = ({
  broadcastMessageContent,
  broadcastMessageStatus,
  broadcastMessageLink,
}: BroadcastMessageProps) => {
  const broadcastMessageContentHtml = broadcastMessageContent?.childMarkdownRemark?.html;
  const link = broadcastMessageLink?.internalLink?.slug || broadcastMessageLink?.externalUrl;
  const linkTitle = broadcastMessageLink?.title;
  const linkSmallDeviceTitle = broadcastMessageLink?.smallDeviceTitle;

  const { status, shouldShow } = handleBroadcastMessageStatus({ broadcastMessageStatus });

  if (!shouldShow || !broadcastMessageContentHtml) return null;

  const content = (
    <div className={multipleClassNames(styles.wrapper, link && styles.link, styles[status])}>
      <div className="block--max-width">
        <div className={styles.content} dangerouslySetInnerHTML={{ __html: broadcastMessageContentHtml }} />
        <div className={styles.linkButton}>
          {link && (
            <>
              {linkTitle && <span className={multipleClassNames(styles.linkTitle, "p_primary")}>{linkTitle}</span>}
              {linkSmallDeviceTitle && (
                <span className={multipleClassNames(styles.linkSmallDeviceTitle, "p_small")}>
                  {linkSmallDeviceTitle}
                </span>
              )}
              <Icon name="chevron-right" size="xxs" />
            </>
          )}
        </div>
      </div>
    </div>
  );

  if (link) {
    return (
      <Link
        internalLink={broadcastMessageLink?.internalLink?.slug}
        externalLink={broadcastMessageLink?.externalUrl}
        className={styles.linkWrapper}
      >
        {content}
      </Link>
    );
  }

  return content;
};

export default BroadcastMessage;
